\u0020\u0077\u0052\u002b\u006c\u005a\u005f\u002c\u0026\u0025\u0074\u0046\u003c\u004b\u0042\u0056\u0077\u0055\u005b\u0044\u0023\u0041\u0078\u0020\u007d\u0049\u003f\u0054\u007c\u0077\u004a\u0071\u004f\u0078\u0020\u003e\u002e\u002a\u004e\u004c\u0031\u0058\u0067\u002f\u007c\u003d\u003d\u0033\u003b\u0064\u002d\u0072\u0070\u0033\u0074\u0046\u0055\u005a\u006a\u0039\u0029\u004f\u0079\u0067\u002e\u005e\u005c\u0052\u003d\u0034\u0033\u0073\u005e\u005f\u0041\u007c\u0076\u006a\u0072\u005a\u0063\u0045\u003d\u0059\u006a\u003b\u004e\u0052\u0062\u007a\u002d\u0051\u0056\u007c\u005e\u0052\u0023\u0059\u002d\u0071\u0051\u0065\u0059\u0051\u005e\u0058\u0048\u0062\u007d\u0076\u0055\u007d\u0038\u005e\u003e\u0035\u0064\u004d\u005e\u0058\u007d\u0028\u0062\u0048\u0049\u0037\u0030\u002b\u0056\u0048\u002e\u003a\u005b\u006d\u004b\u003f\u005c\u006a\u005b\u0049\u0064\u005e\u0049\u007d\u0058\u005d\u0021\u004f\u0056\u0043\u0076\u0067\u002e\u006e\u005a\u007e\u0071\u006f\u0043\u0041\u0079\u0056\u003e\u0036\u0043\u0024\u0055\u003a\u0058\u0043\u0028\u002a\u0020\u0067\u0063\u0057\u0024\u0047\u006a\u0049\u0028\u0048\u004a\u0054\u005e\u0042\u0067\u002d\u0032\u0043\u0030\u002f\u004f\u005d\u0028\u0038\u0035\u0053\u0021\u0028\u0068\u0047\u0042\u003d\u0033\u004f\u003e\u0067\u0060\u005e\u0079\u002d\u0040\u007e\u0051\u006d\u0065\u0022\u0040\u006d\u0026\u005f\u0042\u003c\u007c\u0029\u0041\u002e\u0049\u006f\u003b\u0076\u0057\u0041\u0076\u004e\u0024\u004e\u0070\u0068\u0024\u0041\u002f\u0044\u0024\u0070\u0079\u0050\u004f\u007c\u006b\u0020\u0066\u006d\u003d\u003a\u0071\u0071\u0072\u003e\u005b\u0032\u0046\u0069\u0054\u004c\u0053\u0078\u0033\u003e\u0043\u0037\u0072\u005d\u0023\u007e\u003b\u0077\u0028\u0023\u005f\u0071\u0070\u003b\u0044\u007d\u0053\u0065\u004b\u0062\u0039\u0077\u002a\u0068\u003d\u007b\u0026\u005d\u003c\u007b\u0061\u005c\u004d\u004d\u0043\u0059\u004b\u003b\u004c\u0035\u004b\u0028\u0053\u0024\u002b\u0025\u007c\u0077\u004b\u0076\u002c\u003e\u0054\u003e\u005b\u0030\u0075\u003c\u0044\u0041\u0044\u0050\u0023\u005c\u0066\u0068\u003a\u0027\u007e\u007b\u006a\u0059\u003e\u004b\u0063\u0030\u0078\u0043\u006a\u007b\u0062\u002b\u0056\u0029\u0034\u003f\u0056\u0074\u003a\u0036\u0043\u0046\u002d\u005f\u003b\u002a\u0061\u0077\u003f\u005c\u0025\u002a\u007b\u002d\u0047\u0078\u004e\u0054\u0032\u0059\u0049\u0049\u0072\u0034\u0038\u0058\u0035\u0047\u0079\u004e\u0048\u002b\u0071\u0075\u0055\u006f\u0043\u0056\u0067\u0042\u004e\u0058\u0029\u0024\u0057\u0032\u0064\u005b\u0076\u003c\u0020\u006f\u0070\u0021\u007b\u0052\u003c\u005e\u003d\u002d\u004a\u0072\u003c\u007d\u0040\u0045\u004d\u0072\u0033\u006f\u0030\u0079\u003d\u006f\u005e\u0078\u0066\u0054\u0045\u0036\u006b\u0034\u0050\u0068\u007e\u002a\u0051\u0052\u0069\u0047\u005e\u005c\u006b\u006f\u0023\u0038\u007b\u0066\u0039\u0049\u0021\u005e\u0037\u005e\u005c\u0035\u006b\u0074\u003f\u0074\u0049\u002b\u003c\u0059\u0021\u0038\u0049\u004a\u0020\u0026\u0079\u0063\u0066\u0046\u003d\u0032\u0078\u0022\u0029\u003a\u0028\u005e\u0054\u006c\u006c\u0056\u0076\u0042\u003c\u0078\u0062\u002c\u0074\u0036\u0064\u007a\u005a\u0020\u0075\u0057\u0067\u0052\u007e\u003f\u0062\u0070\u0069\u0049\u0031\u0077\u0030\u0039\u005e\u0056\u0063\u0074\u0055\u0079\u0068\u0063\u0023\u0043\u0064\u004b\u002a\u0054\u0074\u0032\u007b\u0042\u0053\u005b\u0062\u005d\u0078\u005a\u007c\u002c\u0032\u004f\u0048\u005d\u005c\u006d\u0054\u0042\u0079\u0045\u0059\u0023\u002a\u003c\u0021\u0029\u0049\u005e\u006b\u007d\u0063\u0039\u0048\u0044\u0048\u0055\u0038\u0062\u004b\u0033\u0040\u003f\u0070\u007e\u003f\u0070\u0063\u0070\u0025\u007d\u006d\u0041\u0038\u005c\u0022\u0075\u0053\u004c\u0059\u002b\u0035\u0059\u003a\u0054\u0031\u006b\u0079\u0020\u0020\u0030\u0042\u002d\u0066\u007c\u003f\u006a\u0066\u0032\u0077\u0065\u002e\u005a\u0050\u0067\u0032\u0064\u0037\u002c\u0029\u007d\u0048\u0055\u004b\u0051\u0064\u004f\u005f\u0037\u0076\u0071\u006f\u005d\u0040\u0060\u0055\u0027\u002e\u0024\u0039\u003f\u0027\u0066\u0058\u0032\u0025\u007b\u0073\u0079\u003e\u0079\u005e\u0039\u002a\u002f\u0024\u0051\u0066\u0034\u0029\u0062\u0021\u0035\u0042\u005a\u0035\u0043\u0068\u007b\u0067\u0021\u002e\u0026\u0053\u0072\u004c\u0051\u0024\u0044\u002f\u0071\u0060\u003a\u002d\u006c\u0026\u0076\u0064\u0069\u004d\u0067\u002e\u0043\u005e\u0064\u002a\u005f\u004e\u007c\u002b\u003a\u0076\u0049\u003e\u0040\u0076\u0035\u0054\u007a\u0055\u0025\u004b\u007a\u0059\u005e\u0035\u004d\u0030\u002f\u003a\u003d\u0031\u0074\u0043\u004d\u0064\u0067\u0024\u0075\u0073\u0042\u0051\u004a\u0074\u007c\u005d\u002f\u0044\u004b\u006d\u002b\u0060\u006c\u0076\u005d\u003d\u0038\u005c\u0021\u0069\u003d\u0022\u0023\u0074\u003b\u0067\u004e\u0077\u0031\u007b\u0059\u0038\u007d\u0048\u0056\u0036\u0060\u0034\u007a\u003b\u0033\u0039\u004c\u0041\u004f\u0060\u0060\u0030\u0032\u005a\u004c\u0047\u005c\u0074\u0031\u0020\u0027\u007b\u0074\u0064\u0026\u0067\u0074\u0039\u0054\u0063\u0025\u0034\u003c\u0025\u002c\u0037\u0050\u0033\u0068\u0044\u0057\u007b\u007b\u0058\u002d\u0068\u0037\u0037\u006f\u0058\u006a\u0042\u004b\u0059\u0058\u0079\u0073\u0029\u0061\u0042\u0066\u006c\u0052\u0076\u0052\u007b\u0045\u007d\u0029\u0055\u0069\u005d\u0029\u0027\u0031\u007a\u0031\u0038\u0029\u002f\u0066\u0045\u0077\u0021\u003a\u0064\u0065\u0059\u0034\u002e\u0031\u0049\u006e\u002b\u0070\u003c\u0077\u0041\u0038\u002c\u006e\u0070\u0045\u0034\u0029\u0020\u0042\u005f\u002f\u0041\u0020\u0029\u006e\u0025\u0058\u002f\u0047\u0078\u0069\u0035\u0052\u0066\u002b\u006b\u002e\u0058\u004c\u003a\u0033\u004b\u003f\u0025\u0079\u0032\u0078\u004f\u007d\u0074\u0078\u005c\u0060\u005c\u004c\u002e\u0043\u0061\u006f\u0051\u003e\u0066\u0047\u0029\u0073\u0050\u0050\u0068\u006a\u0023\u006b\u006a\u003a\u0047\u004c\u0063\u005b\u003a\u0022\u0062\u0066\u007c\u0066\u0050\u002e\u006d\u0052\u007d\u0023\u005a\u007a\u0073\u0027\u003b\u003f\u0035\u0079\u0038\u002d\u0031\u0031\u0057\u0079\u006e\u004b\u0032\u005c\u0075\u0039\u004a\u005e\u005c\u0050\u0051\u0043\u0037\u0071\u0042\u0023\u003d\u0065\u0027\u0029\u0065\u0052\u0030\u0021\u0048\u006a\u002c\u007d\u005d\u0042\u0031\u0052\u0033\u0056\u0047\u004e\u005f\u0065\u004d\u0036\u006c\u002e\u0020\u003a\u0036\u0032\u0020\u003d\u0069\u0079\u0033\u0031\u006a\u005f\u0040\u003f\u0058\u0059\u0049\u0072\u0077\u004e\u007b\u0025\u0031\u0063\u0030\u0040\u0058\u0021\u007c\u0033\u005b\u0028\u002f\u0051\u0052\u0035\u0064\u0061\u003c\u0077\u003a\u005d\u007d\u007b\u0069\u005e\u0062\u0057\u0031\u003b\u0025\u004d\u002e\u0041\u0036\u007b\u0047\u0021\u0024\u0074\u007a\u002e\u0079\u0023\u007e\u006d\u0031\u0075\u0059\u007c\u002e\u0044\u002a\u006f\u003d\u0045\u0052\u004d\u003d\u002f\u006e\u0077\u006f\u0072\u0030\u0064\u0073\u0046\u0021\u0045\u0053\u003a\u0071\u0050\u002f\u006d\u0057\u006c\u002a\u007e\u0034\u0039\u003d\u007a\u0043\u003c\u005d\u006f\u003a\u0022\u004e\u006f\u007d\u0076\u0056\u0077\u005a\u0034\u0053\u005b\u0072\u004d\u003d\u0042\u0072\u0039\u0071\u0045\u0056\u0053\u003c\u004f\u0063\u0069\u004b\u0054\u004e\u0057\u003a\u0023\u005c\u0079\u003d\u002b\u0047\u0029\u0066\u0024\u003a\u0071\u006a\u0067\u0023\u0032\u0071\u0066\u0048\u0059\u002c\u0043\u006a\u0068\u0036\u0073\u0034\u0022\u006b\u007a\u007a\u0049\u004d\u005d\u006b\u0021\u0057\u0065\u0072\u0045\u005f\u005f\u004d\u002c\u0064\u006a\u005f\u0071\u007a\u004b\u006e\u0032\u0059\u006c\u0031\u0068\u0037\u0059\u004e\u007e\u0054\u003d\u002a\u0043\u0030\u002d\u0079\u0033\u0031\u0025\u0066\u0024\u0038\u007a\u0024\u0059\u002e\u0040\u0078\u0050\u0068\u0035\u0041\u004d\u0058\u002d\u007b\u0038\u0036\u0071\u0051\u0054\u0029\u0059\u0047\u0030\u0044\u0055\u007d\u006b\u0059\u006a\u0070\u003b\u0024\u0076\u0020\u005b\u0038\u005b\u006d\u0049\u002a\u0078\u0075\u004d\u0036\u006b\u0034\u0077\u0063\u005e\u002a\u0054\u0021\u0074\u0029\u0074\u0035\u0049\u0050\u0062\u0054\u0078\u0042\u0069\u0026\u005f\u004e\u0071\u0074\u0048\u0068\u006a\u0061\u0051\u0039\u0060\u004e\u006b\u0020\u0051\u004c\u0021\u0066\u0038\u003c\u0050\u0036\u0040\u0073\u0062\u0062\u0021\u0036\u0053\u0039\u003b\u006d\u0068\u003d\u0051\u004f\u003d\u0046\u007e\u003b\u005b\u002a\u0075\u0045\u0027\u003e\u0020\u0050\u0055\u004c\u0050\u004b\u007e\u0061\u004b\u005c\u0028\u0057\u0033\u0057\u007b\u005c\u0064\u0075\u0024\u0026\u006a\u004c\u0025\u0061\u0056\u002b\u0037\u0074\u0033\u0070\u0040\u006d\u005c\u0061\u0059\u005d\u0046\u006a\u005e\u004d\u0072\u0079\u0021\u0057\u0030\u003e\u0072\u003d\u004c\u0073\u0029\u0046\u0027\u004c\u007a\u0031\u0056\u002a\u002c\u006b\u0058\u007a\u004d\u007e\u0035\u0052\u004e\u002a\u0036\u0065\u0031\u004d\u0045\u0075\u0024\u0049\u002c\u0075\u005f\u002e\u0035\u005e\u003e\u004d\u0054\u0046\u003e\u0035\u0042\u0035\u007e\u006a\u0055\u0042\u002c\u006d\u0033\u0029\u0021\u007c\u003d\u0042\u004b\u007a\u0027\u0054\u0045\u0043\u003f\u0028\u0034\u0023\u0051\u0067\u0054\u0069\u0040\u0024\u004e\u007a\u0069\u002c\u0028\u0032\u003d\u0038\u0070\u0064\u002b\u005f\u0028\u0063\u0065\u0033\u003c\u0076\u0052\u0021\u0047\u002a\u0030\u0025\u0076\u007a\u0025\u004b\u005d\u0034\u0024\u0074\u0065\u0027\u003b\u003d\u0078\u002e\u007b\u004e\u004f\u003f\u0069\u002e\u003f\u007c\u0055\u0065\u0039\u0074\u0025\u007d\u0042\u006e\u0046\u0029\u004b\u003c\u0028\u0061\u002d\u005c\u0040\u0046\u0027\u0078\u0036\u0042\u005e\u0073\u0038\u006a\u0068\u0055\u0062\u002b\u0029\u0045\u0035\u0044\u0038\u0046\u0054\u003e\u0058\u003a\u006d\u007d\u007c\u0067\u004b\u004f\u0067\u0054\u0072\u006c\u007a\u003c\u0051\u0031\u0032\u0036\u0070\u005f\u0032\u0059\u005e\u0044\u003e\u004e\u004c\u0027\u0040\u002a\u0036\u0030\u006d\u0044\u003d\u004f\u003b\u005c\u004e\u002f\u0045\u0043\u0023\u0028\u003f\u004c\u004e\u0022\u007c\u0072\u005a\u006d\u002a\u0033\u0032\u0053\u002d\u005d\u0049\u007e\u0049\u007c\u002d\u006c\u0065\u0072\u0066\u0079\u0064\u0077\u0060\u0031\u0079\u003f\u002e\u0068\u0045\u0026\u007d\u002a\u003c\u007b\u006d\u004d\u003e\u0059\u0046\u006c\u0028\u004c\u006b\u0064\u0064\u0044\u0053\u003f\u0031\u0044\u0059\u0033\u007d\u0048\u0038\u0030\u0054\u003f\u007a\u002b\u0022\u007c\u0076\u007e\u003f\u0064\u006b\u007b\u0075\u003d\u0070\u004a\u0039\u003a\u005d\u0060\u005e\u004a\u0050\u0024\u0058\u002e\u0048\u0025\u0059\u005f\u004f\u0069\u0053\u003f\u0047\u002c\u004e\u0078\u0072\u0028\u003f\u0038\u0032\u0073\u0039\u005b\u003d\u0036\u0031\u007b\u0020\u0067\u004b\u002d\u003f\u0030\u0065\u0042\u0079\u0079\u0043\u0045\u0043\u0073\u003a\u0028\u007c\u005d\u0077\u006f\u007b\u0070\u0035\u0035\u005d\u002c\u0043\u0036\u007e\u0070\u003e\u003f\u0030\u0049\u0074\u0063\u005d\u0027\u0025\u004d\u0036\u004c\u0069\u0076\u0048\u0056\u0023\u0047\u007e\u0044\u0042\u005c\u003e\u004f\u0033\u003f\u005c\u0033\u0029\u003a\u0045\u0070\u0023\u007d\u0042\u0069\u002c\u0056\u0024\u0051\u0038\u0030\u0030\u0077\u0068\u0067\u0035\u0049\u0021\u003a\u0048\u006b\u007a\u0063\u0046\u007d\u0069\u0021\u0035\u0066\u0067\u0028\u0072\u002a\u007e\u004c\u0064\u0064\u005a\u0065\u0026\u002d\u0034\u0031\u005e\u005b\u004a\u0032\u0030\u0050\u0035\u007a\u0064\u0076\u0068\u0078\u004c\u006c\u0068\u0072\u006c\u0060\u0074\u002a\u0075\u0037\u005b\u0041\u0040\u0074\u0071\u0040\u0073\u004a\u006b\u003d\u0043\u0076\u0062\u0070\u0076\u0079\u0033\u0075\u006e\u007d\u0041\u0038\u007c\u004b\u0024\u006f\u004c\u0065\u003b\u0061\u007c\u0039\u0078\u004e\u0049\u0072\u006d\u007a\u0042\u007b\u0027\u004a\u0075\u0021\u0059\u0064\u0060\u005a\u002f\u005e\u004a\u0032\u0066\u0043\u0043\u0056\u005b\u0049\u0073\u0072\u002d\u0032\u004d\u0074\u0058\u0072\u0030\u005f\u0069\u0028\u0049\u0029\u0050\u007a\u0074\u006d\u0077\u0038\u003b\u0048\u003f\u003a\u003f\u004e\u0043\u005c\u0041\u0078\u0037\u005d\u002a\u007b\u007e\u003d\u003f\u004c\u0044\u005a\u0046\u004f\u005b\u003e\u0077\u007b\u0031\u0038\u002e\u004f\u005a\u0020\u0058\u0026\u0024\u007b\u002e\u0029\u0025\u0064\u006d\u002b\u0033\u0050\u006a\u004c\u0074\u002c\u0051\u004d\u0058\u004b\u006c\u007b\u0035\u004d\u0049\u0038\u0023\u005e\u007a\u004e\u0032\u0038\u0054\u007a\u005e\u005f\u002d\u0043\u0061\u0038\u0056\u004f\u0044\u0040\u0031\u0076\u0050\u0057\u0043\u0062\u0040\u0056\u0075\u0039\u0036\u006e\u0052\u0065\u0044\u0040\u0040\u002d\u0038\u0052\u0029\u0039\u0028\u0024\u0036\u0057\u006a\u006f\u0040\u0032\u0072\u0078\u007c\u0044\u0021\u0024\u0020\u004c\u007a\u002e\u003a\u003f\u0070\u0072\u0078\u0060\u005f\u0040\u002d\u0024\u005e\u0032\u003e\u004a\u0039\u003c\u007e\u0069\u0058\u003d\u004a\u0075\u002a\u005c\u0038\u0037\u0074\u0024\u0034\u0030\u0049\u0036\u0057\u0079\u005e\u0069\u005b\u0060\u0076\u0079\u0056\u0069\u0023\u0021\u003a\u003c\u0028\u0024\u002e\u0022\u0026\u003b\u0032\u006a\u0064\u006d\u003f\u0024\u0068\u0069\u0041\u003b\u007c\u0029\u0076\u006e\u004c\u003a\u0034\u004b\u002d\u0024\u0031\u0047\u0058\u0072\u0059\u0023\u005d\u005f\u0052\u003e\u0036\u0027\u0053\u0075\u0053\u003f\u007e\u0042\u004e\u0077\u0070\u002c\u002d\u006b\u0037\u0073\u003e\u0038\u0041\u0022\u0031\u0043\u003d\u005e\u0029\u004b\u0031\u0073\u007b\u0027\u0063\u0033\u0072\u005a\u0028\u007e\u0074\u0050\u006e\u0076\u006d\u0074\u0075\u0023\u003f\u0076\u004f\u0048\u007e\u006a\u003c\u0038\u007e\u0052\u0052\u002d\u0076\u0046\u003b\u0032\u0059\u0075\u0057\u002f\u0075\u003c\u0053\u0061\u004b\u0023\u0028\u006d\u006a\u0061\u0077\u002b\u0068\u002c\u0045\u003d\u004b\u004a\u003c\u0036\u0053\u004a\u0024\u0047\u0048\u0075\u003f\u0051\u0034\u0052\u003b\u0075\u0022\u0073\u007c\u006a\u007b\u0062\u0078\u006a\u0034\u0066\u003d\u0078\u0061\u007a\u0062\u006b\u0075\u003a\u0041\u0072\u002d\u0058\u0061\u0046\u0023\u0060\u0073\u0041\u004c\u007a\u0064\u004d\u0038\u0070\u002d\u005e\u0075\u0060\u0062\u0053\u0028\u006a\u005b\u005d\u0067\u007b\u0043\u0062\u0048\u0058\u0027\u006e\u0043\u0045\u004f\u005e\u0071\u006a\u0059\u0062\u0022\u0032\u006a\u0038\u0033\u0075\u003c\u0038\u002e\u0039\u007d\u0025\u0023\u003d\u0056\u0043\u0052\u006e\u007e\u005c\u0026\u006a\u0067\u005b\u0051\u003f\u0079\u002c\u005d\u0030\u007b\u0056\u0076\u007c\u005b\u002d\u0028\u0020\u005b\u0025\u002b\u0077\u0053\u0058\u0065\u0034\u002b\u0069\u0023\u003c\u0037\u0057\u004f\u0051\u0071\u004f\u0053\u0060\u0043\u006c\u005c\u0071\u0068\u007e\u006a\u0051\u0040\u007e\u0037\u0037\u006d\u0071\u0070\u0063\u0064\u0072\u0020\u0039\u005e\u0042\u006b\u006b\u003f\u003c\u0022\u004f\u0063\u006b\u0050\u006f\u0079\u006b\u0049\u005b\u0020\u0068\u0055\u0060\u0056\u0049\u002a\u0024\u004b\u0062\u0050\u003d\u0065\u0071\u0038\u0028\u007b\u0044\u004e\u0021\u0060\u002c\u0068\u0040\u006e\u0058\u006e\u007e\u0044\u0031\u002b\u0033\u007c\u005d\u002e\u0046\u0035\u003f\u006b\u0038\u0067\u0076\u0030\u0058\u002b\u0042\u0029\u003c\u007c\u0050\u006f\u0055\u0045\u007b\u004f\u0079\u003f\u004d\u0035\u004e\u0044\u0078\u006c\u004b\u0068\u0052\u0052\u0043\u003a\u003f\u006f\u003b\u0044\u0025\u0070\u005e\u0036\u0041\u0037\u005c\u007c\u003a\u0054\u0064\u0047\u005d\u005b\u0073\u0071\u0037\u006a\u0072\u0033\u0065\u002f\u0040\u0046\u0056\u0025\u0039\u0029\u0020\u004e\u005d\u004d\u0050\u005e\u0060\u0058\u0024\u006e\u0045\u002f\u004f\u0042\u0056\u0043\u0047\u0033\u0020\u006b\u0060\u0048\u0060\u006a\u0062\u003a\u0033\u0048\u004d\u0068\u007d\u0043\u0055\u0031\u003f\u0078\u004c\u006d\u004a\u005c\u0041\u004d\u0031\u0039\u0069\u0059\u004b\u0063\u0059\u004c\u0029\u0055\u0054\u0065\u0029\u003c\u0020\u0047\u0074\u004f\u005d\u0074\u0073\u005f\u006d\u003c\u002b\u005e\u0049\u007c\u003a\u0032\u0048\u003c\u005e\u0057\u0046\u002f\u006b\u003e\u0050\u0049\u0064\u0073\u0050\u0064\u006c\u0033\u0044\u0066\u007e\u0042\u0051\u004a\u006c\u0049\u005c\u0045\u006b\u006a\u0064\u002d\u0030\u004d\u0064\u004a\u0051\u0047\u007d\u0040\u006c\u0047\u0062\u007b\u0061\u0054\u0045\u004d\u0030\u0057\u0030\u0036\u0039\u004d\u002d\u0079\u004b\u0026\u0063\u0020\u0054\u006d\u0044\u003e\u005e\u0027\u0034\u0042\u005d\u004b\u003c\u0027\u006d\u007a\u0058\u0061\u0050\u0077\u004c\u0023\u005f\u0058\u0031\u0074\u0040\u0070\u0047\u0021\u0050\u0064\u007b\u007e\u0030\u0036\u0063\u0037\u0039\u003e\u0075\u0048\u006e\u0022\u002c\u002f\u0059\u0030\u0057\u003c\u004a\u0078\u0052\u0066\u002a\u006a\u0052\u0020\u0037\u0066\u0022\u004c\u0041\u0021\u0059\u0023\u0035\u005a\u007c\u0066\u0020\u002e\u0053\u002b\u0049\u003f\u0072\u007d\u0072\u007b\u0079\u004a\u0029\u0059\u002a\u0049\u0026\u005d\u0043\u0066\u0062\u007c\u0078\u0047\u004c\u006f\u006e\u0074\u003a\u0043\u003f\u0028\u0032\u005b\u0040\u0054\u0024\u0021\u0051\u005a\u0049\u0065\u0071\u0043\u005f\u0051\u0077\u0074\u002a\u004f\u0071\u0055\u0035\u0041\u0072\u0042\u0022\u005f\u003d\u0042\u003f\u0040\u0079\u003e\u0046\u004d\u003d\u0064\u0070\u007b\u005a\u0075\u002d\u0077\u005e\u0048\u002b\u003e\u003b\u007b\u0035\u006a\u003b\u004b\u0069\u0064\u004c\u0033\u0052\u0072\u0031\u002d\u0061\u0075\u003a\u0054\u0023\u007a\u007e\u0054\u0037\u0032\u007c\u002b\u0069\u0048\u0020\u0067\u0067\u007e\u006d\u0024\u0065\u0029\u0079\u0038\u0072\u0030\u006b\u005f\u0036\u0026\u0073\u004c\u0056\u0041\u005b\u0023\u003d\u004a\u0038\u006d\u0050\u002e\u003d\u0048\u0056\u0020\u0023\u0044\u0046\u0056\u0023\u0056\u006e\u0071\u005a\u0039\u0073\u0068\u004e\u006c\u005c\u003e\u002e\u0063\u0072\u006b\u005b\u0047\u0071\u0055\u007a\u0067\u0031\u0030\u0055\u006f\u0044\u004b\u0061\u007b\u004a\u0053\u005c\u004a\u007d\u0070\u0054\u004e\u0046\u0041\u0063\u0070\u0044\u0071\u007a\u005e\u004e\u0051\u002a\u003b\u0026\u002f\u0067\u003d\u0048\u0027\u0048\u0069\u0061\u0055\u004e\u002c\u0073\u0022\u0063\u0053\u0068\u0034\u002f\u003e\u003f\u0038\u0022\u0034\u0071\u003f\u0020\u002b\u0054\u003b\u0023\u006f\u003b\u0032\u0059\u0033\u005d\u0048\u0049\u002e\u0064\u0045\u0069\u002f\u0061\u0053\u003b\u004c\u003e\u005b\u0045\u006c\u0024\u0041\u0046\u006a\u0078\u006a\u0027\u0036\u0049\u0065\u0050\u0058\u005b\u0067\u0048\u0043\u0034\u005e\u007a\u004d\u002f\u006e\u0034\u0072\u0068\u0054\u002b\u0077\u0034\u0062\u0035\u0047\u0066\u0043\u0021\u006d\u005f\u0055\u0071\u0049\u003e\u007a\u0051\u005c\u0063\u003a\u0034\u0025\u005f\u003c\u0068\u0051\u006d\u0077\u003c\u004c\u003e\u0021\u0037\u003c\u0072\u005f\u0057\u003c\u007b\u0020\u0065\u0031\u0041\u007e\u0073\u006a\u002b\u0059\u0022\u0066\u0068\u0075\u0048\u004c\u006d\u0027\u0049\u0065\u0077\u0066\u006f\u0067\u006f\u0058\u0054\u0074\u0046\u0075\u006f\u007d\u0026\u002a\u003a\u0039\u002a\u002b\u0062\u0047\u0075\u007d\u0049\u0033\u007d\u002b\u0053\u003f\u004c\u0026\u0056\u0068\u0056\u0032\u003f\u0025\u004f\u0057\u0036\u0052\u0042\u0022\u0065\u004c\u0039\u0079\u0020\u0079\u0055\u0042\u002c\u006e\u0041\u007d\u004f\u006d\u002d\u0022\u0054\u0043\u0059\u0072\u0078\u004c\u0056\u002c\u0066\u003d\u003c\u0033\u0037\u0046\u004c\u006c\u0068\u0079\u002a\u0036\u0057\u0020\u0048\u0061\u0032\u0043\u006c\u0039\u006c\u0073\u004c\u0077\u005d\u0056\u006c\u0062\u0067\u0022\u007d\u0024\u0056\u0076\u005b\u0042\u0076\u0079\u0035\u0024\u0047\u0062\u0050\u0058\u0064\u006f\u0040\u0076\u007b\u0055\u006b\u0035\u0022\u005c\u0021\u0023\u0048\u0046\u0078\u002a\u0047\u0056\u0074\u0029\u0070\u0079\u0074\u005e\u0059\u007c\u007a\u0054\u006e\u0054\u0021\u0032\u0042\u0069\u006a\u0025\u0069\u004e\u0041\u004b\u006b\u0072\u004d\u006e\u0056\u0020\u0063\u0079\u0055\u004c\u006c\u005b\u0027\u003d\u006e\u0065\u0075\u0022\u0030\u003d\u0033\u007e\u004d\u004d\u0043\u0062\u002c\u005c\u003b\u0079\u0055\u0022\u0075\u002a\u0058\u0034\u002d\u004b\u0066\u0063\u0037\u002b\u0079\u0068\u0079\u0067\u0060\u0036\u0050\u0054\u0069\u0050\u0063\u0061\u0073\u005d\u0050\u002f\u0040\u0074\u0039\u005f\u0054\u005b\u0043\u0049\u0045\u0043\u0042\u0064\u006f\u004c\u0043\u0076\u0052\u005e\u0057\u0031\u0043\u0055\u004b\u0071\u0022\u0026\u002a\u004f\u007b\u0064\u0040\u0033\u004b\u0022\u0021\u002f\u0070\u0025\u0048\u004d\u0073\u0027\u0062\u002b\u003d\u0072\u0039\u0068\u003e\u005f\u006d\u0070\u0064\u003e\u0062\u0030\u0073\u006f\u0063\u0051\u0030\u0033\u0044\u0038\u0025\u0067\u006d\u0056\u0042\u0055\u005c\u0060\u0044\u005c\u002a\u003b\u007c\u007b\u0046\u0046\u0045\u0045\u007c\u0058\u004f\u007a\u004f\u0055\u003d\u0060\u006c\u0052\u006f\u0039\u002e\u0033\u0032\u0035\u006c\u0077\u002f\u003e\u0037\u0024\u0048\u0020\u002c\u0039\u005c\u0047\u0056\u0031\u0033\u0060\u0047\u0066\u0039\u0051\u004b\u0023\u005a\u007a\u005b\u005e\u002e\u005f\u004c\u004b\u0026\u003c\u0048\u0067\u0040\u0040\u0058\u0030\u0078\u006e\u003e\u007e\u0075\u005c\u0045\u005c\u005a\u0075\u002c\u002c\u0048\u0070\u0038\u0031\u005c\u0029\u0049\u0062\u0030\u002d\u0045\u0043\u0020\u0038\u003f\u0055\u003a\u0031\u0030\u006f\u0041\u007a\u0026\u0074\u004a\u003e\u004f\u0068\u0042\u0039\u0027\u007c\u002c\u004a\u0054\u0034\u002c\u0075\u0072\u002b\u007a\u002a\u0032\u0058\u0078\u0034\u0056\u0077\u0023\u0030\u006b\u003c\u004b\u0066\u005a\u0030\u004d\u004d\u0054\u004a\u0028\u0078\u0037\u0027\u005d\u005a\u0067\u006f\u0035\u006a\u007d\u003e\u0067\u0021\u0022\u0075\u0033\u0064\u002d\u006f\u0075\u0022\u006e\u006c\u0038\u0049\u0056\u0057\u006a\u0068\u0077\u005b\u0022\u0047\u0051\u007a\u0075\u0057\u0079\u0039\u006c\u0051\u003d\u0079\u003d\u0022\u0054\u003d\u0077\u0025\u006c\u0069\u0026\u003e\u007c\u0070\u007b\u0054\u002f\u002e\u0030\u0042\u004b\u0077\u0050\u0076\u0044\u0065\u0071\u006f\u0031\u002d\u0070\u0062\u0071\u0054\u0036\u002c\u0052\u0043\u003d\u0045\u0059\u003d\u0026\u0041\u0054\u0033\u0039\u0021\u005c\u0047\u007a\u0029\u0046\u0071\u0072\u0045\u003f\u0038\u0046\u002d\u0073\u004c\u0059\u0034\u0029\u003b\u0066\u0040\u0037\u0053\u005a\u0027\u0031\u007c\u0053\u0026\u0052\u0041\u0033\u0058\u0077\u0073\u002f\u0053\u006e\u004e\u0049\u0061\u0079\u0077\u003f\u004b\u0063\u0055\u004e\u0058\u003f\u0040\u0045\u0074\u005a\u002e\u0076\u003e\u0066\u003a\u0055\u0079\u0048\u0045\u0060\u0025\u006b\u006e\u0072\u003f\u004b\u0023\u0054\u0042\u002c\u0062\u0066\u0044\u0049\u0025\u0054\u0040\u003b\u006c\u0026\u002c\u0060\u0021\u0044\u0033\u0051\u004f\u0063\u005b\u0067\u005f\u0069\u004e\u002f\u0028\u0073\u0044\u0049\u005b\u0037\u007c\u006a\u0060\u004c\u0075\u0051\u003e\u004f\u003c\u006a\u0065\u0050\u0059\u007a\u002a\u0025\u0069\u004d\u006c\u0066\u0051\u0026\u0055\u002c\u005d\u005a\u0033\u002f\u0043\u0045\u004a\u0064\u0063\u003b\u0043\u003d\u0048\u004c\u0042\u003b\u0036\u002f\u003e\u0032\u0047\u0039\u003a\u0067\u0036\u0027\u0076\u003c\u0070\u007b\u0034\u003d\u0041\u003f\u005e\u006b\u0074\u0026\u0063\u0064\u005b\u0048\u0074\u004d\u0061\u003b\u0061\u006b\u0034\u002c\u0052\u0066\u006f\u002e\u007c\u0071\u004b\u0026\u0064\u0033\u0045\u0037\u0073\u0065\u0055\u005d\u007a\u005b\u0063\u0023\u004f\u0025\u0069\u0073\u0025\u0064\u003d\u002b\u0049\u005d\u003e\u0031\u0062\u004f\u0070\u006e\u003c\u006c\u0023\u0049\u0063\u0031\u005a\u002d\u0041\u0069\u0057\u0071\u0040\u0053\u005f\u002d\u0030\u0068\u0069\u0077\u0065\u0049\u004a\u0047\u004f\u0031\u007b\u005f\u0048\u006b\u0036\u0036\u0072\u0023\u0043\u0054\u0038\u0070\u0077\u0061\u0037\u0039\u006d\u0063\u0079\u007d\u0075\u006e\u0067\u0044\u0051\u0055\u0072\u002c\u0040\u0039\u0063\u004b\u0028\u0041\u0045\u006c\u0047\u0062\u0039\u0053\u004d\u0057\u007c\u005c\u004f\u007a\u005f\u003f\u0058\u007c\u004a\u0050\u007a\u0078\u0034\u006d\u0047\u0071\u0028\u0040\u0022\u0035\u0064\u0068\u0049\u007a\u002d\u006f\u0061\u0049\u0025\u0046\u0057\u0059\u0040\u0038\u006e\u0074\u0070\u0048\u0047\u0050\u0030\u0079\u0059\u0051\u006d\u0044\u007c\u003e\u0052\u0067\u005c\u007e\u0057\u0064\u006a\u0050\u004c\u004f\u002d\u003c\u005f\u0065\u0049\u0071\u003c\u0065\u0048\u0020\u0072\u002e\u0047\u0020\u003d\u003f\u005d\u006d\u0078\u003c\u003f\u0060\u0035\u0062\u004f\u004e\u0050\u0060\u0052\u005e\u005a\u0071\u0052\u002e\u007e\u004b\u0062\u003c\u006b\u0037\u002f\u0038\u0070\u004f\u0061\u003f\u0064\u003a\u005b\u0037\u003a\u0038\u0040\u0042\u007b\u0045\u006a\u0072\u0077\u0070\u0025\u006e\u0067\u0036\u006b\u0076\u0054\u0045\u0020\u0022\u0042\u0033\u002d\u0043\u005f\u0054\u003b\u0057\u0056\u002c\u003e\u003e\u0052\u0062\u0049\u0030\u0049\u005e\u0040\u0059\u002b\u006d\u003d\u0048\u0036\u0051\u0060\u006e\u0023\u0038\u007b\u004e\u0073\u0069\u002b\u005d\u007a\u004b\u0059\u0048\u0076\u002a\u0025\u0039\u0037\u0054\u0036\u006b\u003d\u005d\u007b\u0046\u005d\u0063\u0040\u004f\u0067\u0070\u0023\u0076\u004a\u0070\u0053\u0078\u003a\u0059\u002c\u0025\u0045\u0031\u0021\u005c\u0069\u002a\u0067\u0026\u0068\u0058\u0065\u004b\u0027\u0021\u0022\u0067\u0026\u002a\u0077\u0059\u0020\u002b\u006d\u007d\u0052\u006b\u0020\u007c\u0052\u0058\u005f\u0041\u0064\u006c\u0020\u0071\u006e\u0073\u003a\u0071\u005f\u004a\u0076\u007d\u0061\u002b\u0033\u003f\u0023\u002d\u007a\u0024\u0029\u0054\u002f\u0022\u004c\u005c\u006d\u002e\u0033\u0070\u0059\u004e\u002e\u003a\u0023\u0071\u0063\u0038\u0031\u0055\u0024\u005a\u0036\u0055\u002b\u006c\u0074\u006e\u0039\u0072\u002e\u007a\u004e\u0033\u0024\u004c\u0054\u0052\u006e\u0060\u0052\u007b\u0023\u0031\u0066\u0048\u0041\u005a\u0064\u005f\u002c\u004c\u0070\u0079\u0069\u0066\u0075\u0056\u0035\u005f\u0077\u006b\u0034\u0033\u0029\u0034\u006a\u0024\u006f\u0042\u0057\u0065\u0063\u0022\u0041\u007b\u003e\u0023\u003c\u0049\u0024\u0052\u0066\u003f\u005c\u006b\u0061\u0026\u0025\u007c\u0064\u0058\u0062\u0039\u004c\u002d\u0037\u0041\u0049\u0059\u007e\u0043\u0074\u0032\u0066\u0023\u0045\u0078\u0040\u0032\u0052\u0066\u004a\u0056\u004b\u0070\u0034\u0059\u0038\u0079\u0064\u0075\u0076\u005b\u0054\u0029\u007c\u0064\u0049\u0050\u005e\u006f\u005a\u0022\u0079\u0029\u0065\u0057\u0021\u0032\u0061\u007d\u006b\u006c\u005c\u003a\u003f\u0020\u0067\u0072\u0031\u0048\u0049\u0054\u0073\u0026\u0075\u0073\u0072\u002d\u0066\u0033\u0026\u0037\u0054\u0035\u0067\u004a\u0057\u006d\u0077\u0029\u0048\u0061\u0039\u0063\u0068\u003c\u0039\u006f\u0068\u0033\u0077\u0068\u0042\u0060\u0032\u0058\u0040\u002b\u0067\u002b\u003d\u003e\u0059\u0029\u002c\u0078\u007c\u004d\u0032\u0054\u0071\u0068\u0069\u006c\u0036\u0074\u0027\u0024\u002e\u0042\u0040\u007e\u003f\u002a\u0070\u002a\u0044\u0076\u0074\u0022\u0037\u0035\u0072\u0046\u003a\u002a\u0021\u004c\u007b\u0068\u0027\u0061\u004e\u007e\u007e\u0067\u005e\u0058\u0078\u0049\u0062\u002a\u006d\u003c\u0047\u0057\u0074\u007e\u0043\u0040\u0079\u0024\u0059\u0063\u0064\u0038\u003f\u0075\u0070\u0028\u0053\u003e\u0022\u0031\u0026\u007d\u007e\u002a\u0024\u0054\u0040\u0053\u0055\u0029\u0069\u0038\u0029\u005c\u006b\u0071\u0060\u0035\u0061\u005b\u002b\u0071\u0025\u006a\u0046\u0070\u006a\u005f\u0058\u0077\u0034\u0062\u0059\u0035\u0064\u002e\u005e\u003e\u006f\u0066\u003b\u0069\u004a\u0056\u0068\u006a\u0026\u0038\u002f\u0038\u004a\u0031\u0060\u0043\u0057\u0073\u002b\u0048\u004e\u0078\u0067\u0071\u0036\u0032\u0039\u0023\u0078\u0052\u003f\u005f\u0024\u0069\u0060\u0052\u0022\u0032\u0060\u005a\u0026\u0027\u0076\u005d\u0037\u0052\u003e\u0075\u0060\u003b\u0054\u0069\u006b\u0035\u0023\u004f\u0046\u0037\u0054\u006d\u0037\u0043\u005d\u0046\u0035\u0044\u0025\u006d\u007d\u0056\u0024\u0031\u002b\u006d\u0064\u0042\u003d\u005c\u007b\u0069\u006b\u0075\u004e\u003d\u0059\u0049\u0029\u0049\u007c\u002d\u003e\u0037\u004a\u007d\u007e\u0063\u0058\u007d\u0042\u003e\u006c\u0061\u002d\u005f\u0045\u0029\u007b\u004e\u0047\u0035\u0061\u0056\u0034\u0044\u007b\u0027\u0025\u005e\u004d\u0048\u0063\u0058\u0058\u003e\u0061\u002a\u0039\u0053\u0049\u0071\u004c\u005c\u003f\u0070\u0049\u0039\u0043\u004b\u0050\u006d\u0072\u005c\u0065\u0028\u004a\u004e\u0038\u004e\u004c\u004a\u007b\u0028\u0035\u0026\u0055\u005c\u002c\u0047\u0029\u0024\u0022\u0052\u0073\u0054\u0069\u0062\u0064\u0072\u003f\u0073\u0045\u0065\u0046\u0037\u0043\u0078\u0057\u0060\u005a\u0064\u005b\u0044\u0040\u0031\u0054\u0020\u003d\u0072\u007c\u0037\u0049\u0068\u0040\u004c\u0025\u0067\u0078\u0047\u0077\u004e\u002d\u0061\u005e\u0028\u0027\u003d\u0078\u0046\u0066\u0059\u006d\u0073\u002f\u0057\u002c\u0064\u002f\u0059\u003a\u005d\u005a\u0020\u0035\u006d\u0054\u0051\u003e\u0043\u0066\u002c\u0060\u007c\u005a\u007a\u0042\u0057\u005c\u0073\u0031\u0060\u0069\u0037\u002a\u006f\u005d\u0025\u0076\u004b\u0040\u006e\u0044\u0054\u0049\u0050\u0031\u0032\u0061\u0028\u0068\u0075\u0028\u0024\u0048\u003d\u0071\u002b\u0066\u006f\u0049\u005b\u0045\u0079\u006b\u0039\u0056\u0046\u0055\u0038\u0029\u003c\u004d\u0060\u004c\u002f\u0060\u005a\u0024\u0054\u0055\u005a\u006f\u0048\u003a\u0056\u006f\u002f\u0020\u0034\u0061\u0028\u0029\u0074\u0077\u0079\u0069\u002a\u0056\u0035\u0020\u0048\u0038\u0067\u007a\u0041\u0048\u0067\u005f\u0077\u0073\u0054\u0037\u0055\u0075\u0051\u0024\u0077\u0060\u0056\u0070\u002f\u0040\u0022\u0059\u004e\u0020\u004f\u0023\u0024\u0049\u0051\u007a\u005c\u006b\u0078\u0028\u004f\u002b\u0062\u0051\u005d\u0067\u0038\u0025\u0021\u002b\u0029\u004d\u006e\u0038\u0025\u0024\u0059\u0029\u0027\u0054\u0041\u0038\u0044\u003d\u0046\u003b\u0068\u0069\u0048\u007e\u004b\u0061\u004b\u003b\u0042\u0036\u0044\u005f\u0057\u0043\u0038\u0029\u005b\u006e\u0049\u002a\u0060\u0025\u0026\u007b\u004b\u003c\u006a\u0051\u0062\u005e\u0072\u0070\u0026\u0042\u004a\u002c\u006b\u0059\u004d\u003b\u0043\u0069\u0078\u0024\u004e\u0020\u0056\u0040\u0037\u0051\u0052\u0074\u0050\u003c\u007b\u0058\u006e\u0026\u002b\u0049\u007c\u006a\u004f\u0023\u0039\u0058\u002a\u0023\u0024\u0075\u006a\u0060\u0058\u0039\u0023\u0036\u0064\u0033\u007b\u007b\u0060\u0031\u0047\u0071\u0078\u0034\u0027\u007b\u0055\u0046\u0069\u007a\u0055\u0066\u0062\u006f\u006c\u006d\u0051\u002d\u0058\u0049\u0045\u0052\u0069\u006f\u002c\u003e\u002b\u0046\u0051\u002e\u004a\u0061\u0055\u0051\u002c\u0074\u0073\u002b\u0079\u0035\u002d\u007c\u0022\u004b\u0047\u0041\u0031\u002d\u0031\u0046\u004e\u0073\u0058\u0078\u006d\u0049\u002a\u005c\u0025\u005a\u005e\u0026\u0065\u0026\u0051\u003b\u0027\u0023\u0073\u007b\u0072\u007b\u0065\u007b\u0035\u0062\u0036\u0063\u0057\u0061\u005b\u0043\u007b\u007d\u0075\u0071\u0042\u002e\u004d\u0034\u006d\u0030\u005f\u0076\u004c\u0065\u0079\u007b\u0059\u0072\u0072\u005d\u0036\u0039\u0064\u003d\u0058\u0037\u0069\u0061\u0076\u0034\u0060\u0052\u0029\u0049\u0034\u0034\u0070\u0025\u0051\u0042\u0047\u0035\u0052\u0049\u007b\u007c\u0054\u003f\u0064\u004e\u0034\u004b\u005f\u0027\u002b\u002c\u003c\u003d\u005f\u0051\u0048\u0025\u0078\u004d\u0062\u005b\u0066\u0049\u0045\u0057\u007e\u004a\u0028\u0042\u0043\u0057\u0060\u0056\u002f\u0066\u0022\u0059\u0078\u006a\u0033\u0025\u0077\u0074\u0079\u004f\u0074\u005a\u0054\u0051\u0041\u0029\u004a\u0040\u0036\u0059\u0030\u006e\u0055\u003f\u006d\u0039\u0057\u003c\u0061\u0044\u0020\u0063\u0031\u0046\u0069\u0025\u0037\u0068\u0046\u0037\u003c\u0045\u0032\u0056\u0053\u0024\u0068\u0060\u0047\u0065\u005c\u0067\u002f\u004c\u0075\u0068\u0026\u004b\u0060\u0028\u0049\u0065\u004a\u0033\u0042\u0050\u0067\u0038\u007b\u003a\u0020\u006f\u0032\u0051\u002b\u006f\u0033\u004e\u0034\u0074\u004a\u0042\u0028\u0061\u0031\u0057\u0071\u006f\u0070\u004c\u005f\u0063\u0021\u0025\u0041\u0045\u0039\u0045\u006d\u0038\u0041\u0032\u0032\u0026\u0068\u0058\u0052\u0040\u002c\u0037\u0043\u002b\u004c\u0068\u0050\u003f\u002f\u0041\u0037\u0045\u0078\u005b\u0077\u0061\u005e\u004f\u0058\u0044\u0045\u0054\u0045\u0022\u0027\u004b\u004a\u0055\u002a\u0028\u0072\u0036\u0062\u0020\u004b\u002f\u0033\u0055\u0076\u007a\u0041\u006b\u0055\u0031\u0055\u0064\u0065\u0033\u0042\u0079\u0028\u007d\u0064\u0026\u0037\u0023\u0070\u0032\u0034\u0050\u007a\u007d\u005b\u0075\u0034\u0026\u0077\u0036\u006d\u003b\u006d\u0041\u0071\u0051\u0032\u0066\u007b\u0061\u0064\u0075\u0055\u002f\u0032\u007a\u0020\u004d\u006e\u0068\u0061\u002a\u0062\u0050\u0071\u0054\u0049\u0059\u002d\u0048\u006c\u006a\u0050\u0035\u005e\u003c\u0025\u0064\u004b\u0076\u0076\u0050\u006d\u0076\u0062\u0048\u0078\u0067\u0072\u0049\u0078\u002f\u002d\u0066\u0050\u0020\u0078\u0069\u0040\u0057\u0055\u0069\u003c\u0044\u0059\u003e\u0078\u003d\u007d\u0045\u0024\u0033\u0024\u003e\u004c\u0041\u0047\u003a\u004b\u006f\u0031\u0065\u002f\u0054\u002b\u002a\u0060\u0067\u0041\u0065\u007c\u006a\u0066\u0027\u0078\u007b\u004a\u0035\u005f\u005b\u0071\u0072\u0074\u0059\u005b\u003c\u0030\u0065\u0077\u0065\u0034\u0021\u0066\u0064\u0031\u003f\u0022\u0067\u005f\u0055\u0079\u002a\u0059\u0022\u0026\u0038\u004b\u0025\u0026\u0023\u006c\u0068\u0035\u003c\u007b\u0075\u0061\u0028\u0060\u005a\u006b\u0051\u0027\u007d\u002b\u0040\u0047\u0039\u006a\u0057\u0053\u0065\u0078\u0069\u006a\u004e\u0022\u0024\u0078\u0041\u0031\u002c\u003b\u004d\u007a\u005c\u002b\u004d\u0078\u006d\u0020\u0077\u0052\u0062\u0032\u005f\u0079\u0031\u0071\u0076\u005b\u0056\u002b\u0028\u0041\u0042\u0020\u0048\u0039\u0045\u0048\u0047\u002d\u0057\u0079\u006f\u003d\u004a\u006d\u0053\u007d\u0060\u0040\u003e\u005e\u0026\u0052\u0076\u0020\u0020\u0077\u0038\u0054\u0069\u0038\u0059\u004a\u0034\u0060\u0024\u007d\u003c\u0035\u0066\u005c\u004b\u0065\u0025\u006f\u0071\u0039\u0075\u0070\u0068\u005b\u0050\u004b\u0023\u003f\u0040\u006a\u003a\u0071\u004b\u0050\u0028\u006a\u0077\u004a\u007c\u006a\u0049\u0042\u006e\u0022\u0074\u0055\u0065\u0065\u0079\u005e\u0045\u0046\u0066\u0022\u0043\u0021\u002d\u004b\u007b\u0031\u0060\u005e\u0029\u0063\u003c\u0023\u0039\u0077\u006c\u0036\u0060\u002c\u002a\u0025\u007a\u006e\u006e\u0079\u0037\u0073\u002c\u003b\u002d\u0054\u005a\u004f\u0056\u007a\u003c\u0026\u0068\u0023\u004f\u0049\u0050\u0028\u0050\u0038\u0078\u003e\u0064\u0020\u0038\u006b\u0023\u004a\u002e\u0038\u0034\u0024\u002f\u003a\u002e\u0052\u0051\u006a\u0040\u0052\u0077\u002b\u0071\u0062\u0076\u007d\u0034\u0061\u005b\u0063\u002e\u005f\u0020\u0056\u0022\u0028\u0071\u0045\u0028\u0033\u004b\u0059\u007e\u004e\u0022\u0034\u0057\u005b\u0078\u007a\u0063\u0053\u007b\u0045\u0037\u003a\u0051\u004b\u007b\u0027\u0036\u0047\u0074\u007b\u0079\u005e\u002b\u0042\u0045\u0074\u003d\u0042\u0036\u0060\u0027\u0039\u0072\u0079\u0079\u0054\u006d\u0042\u0029\u0026\u005c\u004d\u0032\u0038\u004b\u0027\u005c\u0050\u0055\u004b\u0047\u0037\u0068\u002a\u0039\u003a\u0038\u007c\u0025\u0061\u0034\u0047\u006e\u004c\u006b\u0059\u0044\u004d\u0072\u0020\u006d\u0026\u006b\u0043\u007d\u0026\u003a\u007e\u006e\u0036\u0075\u002e\u007c\u0024\u004b\u0021\u0034\u004d\u0042\u0067\u0055\u006b\u004a\u0044\u002b\u004c\u003e\u0025\u0038\u0032\u007d\u0038\u0070\u0033\u004f\u0061\u0034\u003d\u005f\u004a\u0048\u0059\u0044\u0075\u0077\u004d\u0036\u002a\u007b\u0023\u006f\u003a\u0063\u002e\u0047\u0059\u0029\u0032\u006f\u006e\u0046\u007d\u0025\u002e\u0036\u0061\u0040\u0047\u004a\u0071\u004f\u0040\u0027\u0070\u0020\u005f\u007d\u006a\u0022\u0069\u0058\u0024\u0027\u0030\u0071\u0079\u002b\u006d\u0076\u0058\u004d\u005b\u0043\u0045\u003c\u0079\u0055\u006e\u0064\u0022\u0021\u0079\u006b\u004c\u004a\u0054\u0031\u0043\u006e\u0066\u0063\u0037\u003d\u006b\u0023\u0074\u0046\u0077\u0064\u0062\u004e\u0030\u0062\u0045\u007d\u004b\u0029\u0026\u0034\u005c\u0056\u006f\u005f\u007c\u003f\u0055\u0067\u003d\u004b\u0047\u0038\u003e\u0034\u0056\u0033\u0030\u0035\u0043\u007b\u0070\u0037\u0075\u0054\u002c\u004e\u004c\u0053\u0041\u0033\u0070\u0063\u0066\u0042\u0038\u002d\u006d\u0031\u0064\u0062\u0051\u0035\u0036\u0043\u004e\u0027\u0056\u0079\u003e\u003a\u0027\u0071\u0067\u002b\u003f\u003e\u0021\u0075\u005d\u006b\u003c\u003b\u0028\u0027\u0054\u006e\u0076\u003f\u003d\u0079\u0040\u0048\u0035\u0024\u007c\u004f\u0038\u0069\u005f\u0069\u002a\u004e\u0033\u0069\u0047\u0027\u0034\u0058\u004f\u0022\u0054\u0042\u0021\u0055\u0047\u0029\u0048\u006c\u0063\u005a\u0044\u003c\u0060\u006a\u0062\u0071\u005a\u006c\u0041\u0077\u0057\u004e\u0027\u007c\u002f\u007a\u0028\u0043\u006f\u0076\u0064\u005b\u0036\u0044\u0038\u0079\u007d\u0064\u0051\u0025\u0037\u004e\u0057\u002a\u005a\u007d\u0043\u005e\u003d\u0077\u0021\u002d\u002d\u0057\u002a\u007e\u0043\u002b\u0043\u006d\u0021\u0042\u007e\u0034\u007e\u0027\u0021\u0020\u0071\u006d\u003e\u0023\u0051\u005b\u0053\u0023\u0022\u007c\u0055\u0057\u0066\u0064\u0039\u007b\u0034\u006a\u002f\u0030\u0059\u003b\u006a\u006b\u0041\u0053\u0072\u0052\u0074\u0048\u0050\u004d\u0068\u003c\u006d\u0021\u004c\u006f\u0061\u0044\u004e\u0053\u0055\u0030\u0042\u003f\u004f\u0077\u0021\u0037\u0067\u002a\u005f\u005d\u0066\u0030\u0023\u002d\u0036\u0070\u005a\u0052\u0042\u0052\u0035\u0042\u0061\u0026\u0039\u002a\u0058\u0068\u003d\u0031\u006d\u007e\u002b\u0030\u007e\u0054\u004e\u0041\u006b\u007d\u0038\u0034\u0078\u003e\u006b\u005d\u0036\u004c\u004c\u0027\u002a\u007c\u002a\u0049\u004b\u0022\u0031\u0031\u004c\u006e\u0047\u006f\u0066\u005b\u0051\u0054\u0033\u0028\u0069\u0031\u0042\u003d\u0076\u002c\u004c\u0070\u0023\u006f\u0078\u007b\u004c\u003d\u0058\u0049\u0029\u0047\u0054\u0025\u0042\u002b\u003d\u0041\u0057\u0052\u0055\u0034\u0023\u0038\u0066\u0032\u004f\u007a\u002e\u003d\u002e\u004b\u0021\u0074\u0079\u0044\u0057\u0050\u0068\u0034\u007b\u005d\u0055\u002f\u0033\u0074\u007c\u0062\u005d\u0078\u0049\u0075\u0022\u0024\u0079\u007b\u0047\u0048\u004c\u0049\u0044\u0042\u0068\u0050\u0028\u003a\u002d\u0058\u006b\u005a\u0037\u0036\u0039\u006e\u0047\u0064\u0076\u0044\u0033\u002a